import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireBlocks Configurator Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-1-1.md","filePath":"aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-1-1.md","lastUpdated":1786969392000}`),a={name:`aireblock-releases/AireBlocksConfigurator/aireblocks-configurator-v1-1-1.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireblocks-configurator-release-notes" tabindex="-1"><span class="fsc-product"><img src="/AireBlocks_Favicon.png"> AireBlocks Configurator Release Notes</span> <a class="header-anchor" href="#aireblocks-configurator-release-notes" aria-label="Permalink to “AireBlocks Configurator Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.1.1<br><strong>Release Date:</strong> 26 August 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>Shareable, Paginated Audit Log Links (SUITECONF-287)</li><li>Crop Your Logo When Uploading (SUITECONF-313)</li><li>Bulk Export and Import of Variables (SUITECONF-375)</li><li>Bulk Export and Import of Secrets (SUITECONF-381)</li><li>Search Variables by Key or Value (SUITECONF-386)</li><li>Shareable Theme Page Tabs (SUITECONF-403)</li></ul><h4 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h4><ul><li>Clearer Icons for Audit Log Sources (SUITECONF-305)</li><li>More Flexible Audit Source Filtering (SUITECONF-325)</li><li>Cleaner Variable Editor Layout (SUITECONF-387)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed AireVault Access Checks (SUITECONF-391)</li><li>Fixed Logo Upload for Tenants Without an Existing Theme (SUITECONF-393)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="shareable-paginated-audit-log-links-suiteconf-287" tabindex="-1">Shareable, Paginated Audit Log Links (SUITECONF-287) <a class="header-anchor" href="#shareable-paginated-audit-log-links-suiteconf-287" aria-label="Permalink to “Shareable, Paginated Audit Log Links (SUITECONF-287)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Audit log pagination is now reflected in the page&#39;s URL. Refreshing the page keeps you on the same page of results, and you can share a direct link to a specific page of the audit log.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now bookmark or share a link straight to a particular page of audit log results, and refreshing your browser won&#39;t send you back to the start.</p></div><h4 id="crop-your-logo-when-uploading-suiteconf-313" tabindex="-1">Crop Your Logo When Uploading (SUITECONF-313) <a class="header-anchor" href="#crop-your-logo-when-uploading-suiteconf-313" aria-label="Permalink to “Crop Your Logo When Uploading (SUITECONF-313)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>When uploading a tenant logo, you can now crop the image to the required size and aspect ratio directly within the upload dialogue, similar to the image cropping tools found on social media platforms.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You no longer need to resize or crop your logo image yourself before uploading it — you can adjust the crop directly in AireBlocks Configurator to get the right fit.</p></div><h4 id="bulk-export-and-import-of-variables-suiteconf-375" tabindex="-1">Bulk Export and Import of Variables (SUITECONF-375) <a class="header-anchor" href="#bulk-export-and-import-of-variables-suiteconf-375" aria-label="Permalink to “Bulk Export and Import of Variables (SUITECONF-375)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Variables can now be exported to a JSON file and re-imported in bulk, making it easier to move or back up large sets of variables at once rather than adding them individually.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>If you manage a lot of variables, you can now export them all in one go and bulk-import them elsewhere, saving you from adding them one at a time.</p></div><h4 id="bulk-export-and-import-of-secrets-suiteconf-381" tabindex="-1">Bulk Export and Import of Secrets (SUITECONF-381) <a class="header-anchor" href="#bulk-export-and-import-of-secrets-suiteconf-381" aria-label="Permalink to “Bulk Export and Import of Secrets (SUITECONF-381)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Secrets can now be exported and imported in the same way as variables, allowing them to be moved or backed up in bulk rather than one at a time.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can now export and re-import your secrets in bulk, making it quicker to migrate or back up larger sets of them.</p></div><h4 id="search-variables-by-key-or-value-suiteconf-386" tabindex="-1">Search Variables by Key or Value (SUITECONF-386) <a class="header-anchor" href="#search-variables-by-key-or-value-suiteconf-386" aria-label="Permalink to “Search Variables by Key or Value (SUITECONF-386)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>You can now search for variables by their key or their value, rather than only being able to browse the full list.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Finding the variable you need is now much quicker — just search for its name or its value instead of scrolling through the whole list.</p></div><h4 id="shareable-theme-page-tabs-suiteconf-403" tabindex="-1">Shareable Theme Page Tabs (SUITECONF-403) <a class="header-anchor" href="#shareable-theme-page-tabs-suiteconf-403" aria-label="Permalink to “Shareable Theme Page Tabs (SUITECONF-403)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The active tab on the Theme page is now reflected in the URL, matching the existing behaviour on the AireVault page.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can share a link that opens directly to a specific tab on the Theme page, and refreshing the page will no longer reset you back to the first tab.</p></div><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><hr><h4 id="clearer-icons-for-audit-log-sources-suiteconf-305" tabindex="-1">Clearer Icons for Audit Log Sources (SUITECONF-305) <a class="header-anchor" href="#clearer-icons-for-audit-log-sources-suiteconf-305" aria-label="Permalink to “Clearer Icons for Audit Log Sources (SUITECONF-305)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Audit log entries now display updated icons, including a new icon for AireBlocks Configurator, making it easier to identify which product an audit event originated from.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>It&#39;s now easier to tell at a glance which product an audit log entry relates to, thanks to clearer, updated icons.</p></div><h4 id="more-flexible-audit-source-filtering-suiteconf-325" tabindex="-1">More Flexible Audit Source Filtering (SUITECONF-325) <a class="header-anchor" href="#more-flexible-audit-source-filtering-suiteconf-325" aria-label="Permalink to “More Flexible Audit Source Filtering (SUITECONF-325)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>The audit log filter previously labelled &quot;Product&quot; has been renamed to &quot;Source&quot; throughout, and you can now type in a custom source rather than being limited to the predefined list.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>You can filter audit logs by any source you type in, not just the ones offered by default, making it easier to find the entries you&#39;re looking for.</p></div><h4 id="cleaner-variable-editor-layout-suiteconf-387" tabindex="-1">Cleaner Variable Editor Layout (SUITECONF-387) <a class="header-anchor" href="#cleaner-variable-editor-layout-suiteconf-387" aria-label="Permalink to “Cleaner Variable Editor Layout (SUITECONF-387)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Tidied up the layout of the variable create/edit screen: the key field now spans the full width, and the scope button has been resized to align with the Scope and Value fields.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>The variable editing screen is now tidier and easier to read, with fields lined up more consistently.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-airevault-access-checks-suiteconf-391" tabindex="-1">Fixed AireVault Access Checks (SUITECONF-391) <a class="header-anchor" href="#fixed-airevault-access-checks-suiteconf-391" aria-label="Permalink to “Fixed AireVault Access Checks (SUITECONF-391)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue in AireVault where an &quot;access denied&quot; message could be shown incorrectly, and the AireVault navigation item could appear even when a user lacked access to both variables and secrets. Access denied is now only shown, and the navigation item only hidden, when a user has no access to either.</p></div><h4 id="fixed-logo-upload-for-tenants-without-an-existing-theme-suiteconf-393" tabindex="-1">Fixed Logo Upload for Tenants Without an Existing Theme (SUITECONF-393) <a class="header-anchor" href="#fixed-logo-upload-for-tenants-without-an-existing-theme-suiteconf-393" aria-label="Permalink to “Fixed Logo Upload for Tenants Without an Existing Theme (SUITECONF-393)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Fixed an issue where a tenant without an existing theme in the database was unable to upload a logo or background image.</p></div>`,47)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};